        accountGroup.MapPost("/info", async Task<Results<Ok<InfoResponse>, ValidationProblem, NotFound>>
            (ClaimsPrincipal claimsPrincipal, [FromBody] InfoRequest infoRequest, HttpContext context, [FromServices] IServiceProvider sp) =>
        {
            var userManager = sp.GetRequiredService<UserManager<TUser>>();
            if (await userManager.GetUserAsync(claimsPrincipal) is not { } user)
            {
                return TypedResults.NotFound();
            }

            if (!string.IsNullOrEmpty(infoRequest.NewEmail) && !_emailAddressAttribute.IsValid(infoRequest.NewEmail))
            {
                return CreateValidationProblem(IdentityResult.Failed(userManager.ErrorDescriber.InvalidEmail(infoRequest.NewEmail)));
            }

            if (!string.IsNullOrEmpty(infoRequest.NewPassword))
            {
                if (string.IsNullOrEmpty(infoRequest.OldPassword))
                {
                    return CreateValidationProblem("OldPasswordRequired",
                        "The old password is required to set a new password. If the old password is forgotten, use /resetPassword.");
                }

                var changePasswordResult = await userManager.ChangePasswordAsync(user, infoRequest.OldPassword, infoRequest.NewPassword);
                if (!changePasswordResult.Succeeded)
                {
                    return CreateValidationProblem(changePasswordResult);
                }
            }

            if (!string.IsNullOrEmpty(infoRequest.NewEmail))
            {
                var email = await userManager.GetEmailAsync(user);

                if (email != infoRequest.NewEmail)
                {
                    await SendConfirmationEmailAsync(user, userManager, context, infoRequest.NewEmail, isChange: true);
                }
            }

            return TypedResults.Ok(await CreateInfoResponseAsync(user, userManager));
        });

        async Task SendConfirmationEmailAsync(TUser user, UserManager<TUser> userManager, HttpContext context, string email, bool isChange = false)
        {
            if (confirmEmailEndpointName is null)
            {
                throw new NotSupportedException("No email confirmation endpoint was registered!");
            }

            var code = isChange
                ? await userManager.GenerateChangeEmailTokenAsync(user, email)
                : await userManager.GenerateEmailConfirmationTokenAsync(user);
            code = WebEncoders.Base64UrlEncode(Encoding.UTF8.GetBytes(code));

            var userId = await userManager.GetUserIdAsync(user);
            var routeValues = new RouteValueDictionary()
            {
                ["userId"] = userId,
                ["code"] = code,
            };

            if (isChange)
            {
                // This is validated by the /confirmEmail endpoint on change.
                routeValues.Add("changedEmail", email);
            }

            var confirmEmailUrl = BuildPortalConfirmEmailUrl(context, userId, code, isChange ? email : null)
                ?? linkGenerator.GetUriByName(context, confirmEmailEndpointName, routeValues)
                ?? throw new NotSupportedException($"Could not find endpoint named '{confirmEmailEndpointName}'.");

            await emailSender.SendConfirmationLinkAsync(user, email, confirmEmailUrl);
        }

        return new IdentityEndpointsConventionBuilder(routeGroup);
    }

    private static string? BuildPortalConfirmEmailUrl(
        HttpContext context,
        string userId,
        string code,
        string? changedEmail)
    {
        var portal = ResolvePortalBaseUrl(context);
        if (string.IsNullOrWhiteSpace(portal))
            return null;

        var url =
            $"{portal.TrimEnd('/')}/Login/ConfirmEmail?userId={Uri.EscapeDataString(userId)}&code={Uri.EscapeDataString(code)}";
        if (!string.IsNullOrWhiteSpace(changedEmail))
            url += $"&changedEmail={Uri.EscapeDataString(changedEmail)}";
        return url;
    }

    private static string? BuildPortalResetPasswordUrl(HttpContext context, string email, string code)
    {
        var portal = ResolvePortalBaseUrl(context);
        if (string.IsNullOrWhiteSpace(portal))
            return null;

        return
            $"{portal.TrimEnd('/')}/Login/ResetPassword?email={Uri.EscapeDataString(email)}&code={Uri.EscapeDataString(code)}";
    }

    private static string? ResolvePortalBaseUrl(HttpContext context)
    {
        var configuration = context.RequestServices.GetService<IConfiguration>();
        return FirstNonEmpty(
            configuration?["EmailService:PortalUrl"],
            configuration?["AppSettings:PortalUrl"],
            Environment.GetEnvironmentVariable("QUICKCODE_PORTAL_URL"));
    }

    private static string? FirstNonEmpty(params string?[] values) =>
        values.FirstOrDefault(v => !string.IsNullOrWhiteSpace(v))?.Trim();

    private static ValidationProblem CreateValidationProblem(string errorCode, string errorDescription) =>
        TypedResults.ValidationProblem(new Dictionary<string, string[]> {
            { errorCode, [errorDescription] }
        });

    private static string GenerateJwtToken(ApiUser user, IConfigurationSection jwtSettings)
    {
        var claims = new List<Claim>
        {
            new Claim(JwtRegisteredClaimNames.Sub, user.Id),
            new Claim(JwtRegisteredClaimNames.Email, user.Email!),
            new Claim("PermissionGroupName", user.PermissionGroupName!),
            new Claim(JwtRegisteredClaimNames.Jti, Guid.NewGuid().ToString())
        };

        var signingCredentials = new SigningCredentials(GetUserJwtRsaKey(), SecurityAlgorithms.RsaSha256);

        var token = new JwtSecurityToken(
            issuer: jwtSettings["Issuer"],
            audience: jwtSettings["Audience"],
            claims: claims,
            expires: DateTime.UtcNow.AddMinutes(jwtSettings.GetValue<int>("AccessTokenExpirationMinutes")),
            signingCredentials: signingCredentials);

        return new JwtSecurityTokenHandler().WriteToken(token);
    }

    private static RsaSecurityKey? _userJwtRsaKey;
    private static readonly object UserJwtKeyLock = new();

    /// <summary>
    /// User JWTs are signed with an RSA private key (RS256, base64 PKCS#8) held only by the
    /// Identity module. The same key material also verifies tokens in /validate.
    /// </summary>
    private static RsaSecurityKey GetUserJwtRsaKey()
    {
        if (_userJwtRsaKey != null)
        {
            return _userJwtRsaKey;
        }

        lock (UserJwtKeyLock)
        {
            if (_userJwtRsaKey != null)
            {
                return _userJwtRsaKey;
            }

            var privateKey = Environment.GetEnvironmentVariable("USER_JWT_PRIVATE_KEY")
                ?? Environment.GetEnvironmentVariable("QUICKCODE_USER_JWT_PRIVATE_KEY");

            if (string.IsNullOrWhiteSpace(privateKey))
            {
                throw new InvalidOperationException(
                    "User JWT private key is missing. Set USER_JWT_PRIVATE_KEY or QUICKCODE_USER_JWT_PRIVATE_KEY (base64 PKCS#8).");
            }

            var rsa = RSA.Create();
            rsa.ImportPkcs8PrivateKey(Convert.FromBase64String(privateKey.Trim()), out _);
            _userJwtRsaKey = new RsaSecurityKey(rsa);
            return _userJwtRsaKey;
        }
    }

    private static string GenerateRefreshToken()
    {
        return Convert.ToBase64String(RandomNumberGenerator.GetBytes(64));  // Refresh token için rastgele veri üret
    }
    
    private static ClaimsPrincipal ValidateJwtToken(string token, IConfigurationSection jwtSettings)
    {
        var tokenHandler = new JwtSecurityTokenHandler();

        try
        {
            var validationParameters = new TokenValidationParameters
            {
                ValidateIssuer = true,
                ValidateAudience = true,
                ValidateLifetime = true,
                ValidateIssuerSigningKey = true,
                ValidIssuer = jwtSettings["Issuer"],
                ValidAudience = jwtSettings["Audience"],
                IssuerSigningKey = GetUserJwtRsaKey(),
                ValidAlgorithms = new[] { SecurityAlgorithms.RsaSha256 },
                ClockSkew = TimeSpan.FromSeconds(2)
            };
            
            var principal = tokenHandler.ValidateToken(token, validationParameters, out var validatedToken);
            return principal;
        }
        catch (Exception)
        {
            return null!;
        }
    }
    
    private static async Task TrySendPasswordChangedEmailAsync<TUser>(
        IServiceProvider sp,
        UserManager<TUser> userManager,
        TUser user)
        where TUser : class
    {
        try
        {
            var emailSender = sp.GetService<IIdentityAccountEmailSender>();
            var email = await userManager.GetEmailAsync(user);
            if (emailSender is null || string.IsNullOrWhiteSpace(email))
                return;

            var displayName = user is ApiUser apiUser
                ? $"{apiUser.FirstName} {apiUser.LastName}".Trim()
                : email;
            await emailSender.SendPasswordChangedAsync(email, displayName);
        }
        catch
        {
            // Password is already changed; email is best-effort.
        }
    }

    private static async Task<TUser?> ResolveCurrentUserAsync<TUser>(UserManager<TUser> userManager, ClaimsPrincipal principal)
        where TUser : class
    {
        if (await userManager.GetUserAsync(principal) is { } user)
            return user;

        var userId = principal.FindFirstValue(ClaimTypes.NameIdentifier)
                     ?? principal.FindFirstValue(JwtRegisteredClaimNames.Sub);
        if (!string.IsNullOrWhiteSpace(userId)
            && !string.Equals(userId, "gateway", StringComparison.OrdinalIgnoreCase))
        {
            user = await userManager.FindByIdAsync(userId);
            if (user is not null)
                return user;
        }

        var email = principal.FindFirstValue(ClaimTypes.Email)
                    ?? principal.FindFirstValue(JwtRegisteredClaimNames.Email);
        if (!string.IsNullOrWhiteSpace(email))
            return await userManager.FindByEmailAsync(email);

        return null;
    }

    private static ValidationProblem CreateValidationProblem(IdentityResult result)
    {
        // We expect a single error code and description in the normal case.
        // This could be golfed with GroupBy and ToDictionary, but perf! :P
        Debug.Assert(!result.Succeeded);
        var errorDictionary = new Dictionary<string, string[]>(1);

        foreach (var error in result.Errors)
        {
            string[] newDescriptions;

            if (errorDictionary.TryGetValue(error.Code, out var descriptions))
            {
                newDescriptions = new string[descriptions.Length + 1];
                Array.Copy(descriptions, newDescriptions, descriptions.Length);
                newDescriptions[descriptions.Length] = error.Description;
            }
            else
            {
                newDescriptions = [error.Description];
            }

            errorDictionary[error.Code] = newDescriptions;
        }

        return TypedResults.ValidationProblem(errorDictionary);
    }

    private static async Task<InfoResponse> CreateInfoResponseAsync<TUser>(TUser user, UserManager<TUser> userManager)
        where TUser : class
    {
        return new()
        {
            Email = await userManager.GetEmailAsync(user) ?? throw new NotSupportedException("Users must have an email."),
            IsEmailConfirmed = await userManager.IsEmailConfirmedAsync(user),
        };
    }

    // Wrap RouteGroupBuilder with a non-public type to avoid a potential future behavioral breaking change.
    private sealed class IdentityEndpointsConventionBuilder(RouteGroupBuilder inner) : IEndpointConventionBuilder
    {
        private IEndpointConventionBuilder InnerAsConventionBuilder => inner;

        public void Add(Action<EndpointBuilder> convention) => InnerAsConventionBuilder.Add(convention);
        public void Finally(Action<EndpointBuilder> finallyConvention) => InnerAsConventionBuilder.Finally(finallyConvention);
    }

